[Form]
public class TFMExpressionEditor extends FormRun
{
    Common							callingRecord;
    FieldId							returnFieldId;
    TFMExpressionEditorFormClass	formClass;
    FormStringControl               expressionStringControl;

}

    public display str currentExpression()
    {
		if (formClass)
        {
            return formClass.currentExpression();
        }
        return '';
    }

/// <summary>
///
/// </summary>
/// <returns></returns>
public boolean closed()
{
    boolean ret;

    ret = super();
    expressionStringControl.modified();
    return ret;
}

    public void run()    
	{
        SysDictTable		dt;
        SysDictField		sdf;
        SetEnumerator		fields;
        str					fieldName;
        ListEnumerator		lEnum = TFMExpressions::getPossibleExpressions().getEnumerator();
        int					pos;
        int					endPos;
        str					existingExp, existingParm;
        List				expList;
        ListEnumerator		expListEnum;
        str					preFixStr;
        formClass	= new TFMExpressionEditorFormClass(ParmGroup,ParmListBox, FirstParmText,CurrentExpressionString,HtmlHelpView);

		super();
        callingRecord  = element.args().record();
        expressionStringControl = element.args().caller();
        dt = new SysDictTable(callingRecord.tableId);
        if (dt)
        {
            fields = dt.fields().getEnumerator();
            while(fields.moveNext())
            {
                sdf = fields.current();
                fieldName = sdf.name();

                if (sdf.typeId() == extendedTypeNum(TFMExpression))
                {
                    returnFieldId = sdf.id();
                    ExpressionString.text(callingRecord.(returnFieldId));
                }
            }
        }
        pos = strScan(ExpressionString.text(),'(',0,1000);

		if (pos)
        {
            existingExp = subStr(ExpressionString.text(),1,pos - 1);
            endPos = strScan(ExpressionString.text(),')',0,1000);
            existingParm = subStr(ExpressionString.text(),pos + 1, endPos - pos - 1);
            expList = TFMHelper::strSplit(existingExp,' ');
            postFixString.text(subStr(ExpressionString.text(),endPos + 1,10000));
			if (expList.elements())
            {
				// Prefix exists
                existingExp = '';
                expListEnum = expList.getEnumerator();
				while (expListEnum.moveNext())
                {                    
                    preFixStr += existingExp + ' ';
					//prefixString.text(prefixString.text()+ existingExp + ' ');
                    existingExp = expListEnum.current();
                }
            }
        }
        else if (strScan(ExpressionString.text(),'[value]',0,1000))
        {
            pos = strScan(ExpressionString.text(),'[value]',0,1000);
            prefixStr = subStr(ExpressionString.text(),1,pos - 1);

            postFixString.text(subStr(ExpressionString.text(),pos + 7,10000));
            existingExp = '[value]';
		}
        else
		{
            prefixStr = ExpressionString.text();
		}
        prefixString.text(prefixStr);

        CommandListBox.add('None');
        CommandListBox.add('[value]');

		while (lEnum.moveNext())
        {
            CommandListBox.add(lEnum.current());

        }
        CommandListBox.selectText(existingExp);
        CommandListBox.selectionChange();

        formClass.updateParmGroup(existingExp,existingParm);

        formClass.updateExpression();
    }

/// <summary>
///
/// </summary>
/// <param name = "_p1"></param>
/// <returns></returns>
public int task(int _p1)
{
    int ret;

    ret = super(_p1);

    if (_p1 == 272) // Save button clicked
    {
        if (callingRecord)
        {
            callingRecord.(returnFieldId) = prefixString.text() + ' ' + currentExpressionString.text() + (currentExpressionString.text() && postfixString.text() ? ' ' : '') + postfixString.text();
            ExpressionString.text(callingRecord.(returnFieldId));
        }
        else if (expressionStringControl)
        {
            expressionStringControl.text(prefixString.text() + ' ' + currentExpressionString.text() + (currentExpressionString.text() && postfixString.text() ? ' ' : '') + postfixString.text());
            ExpressionString.text(expressionStringControl.text());
            expressionStringControl.modified();
        }
    }

    return ret;
}

        /// <summary>
        ///
        /// </summary>
        /// <returns></returns>
        public int selectionChange()
        {
			int ret = super();
            formClass.commandBoxChanged(this);
            formClass.updateExpression();
            return ret;
        }

/// <summary>
///
/// </summary>
/// <returns></returns>
public int selectionChange()
{
    int ret;

    ret = super();

    formClass.parmGroupSelectionChanged();

    formClass.updateExpression();

    return ret;
}
